   "    }\n  });\n  fac_render();\n  const ms = FAC.estado && FAC.estado.microsip;\n  if (!FAC.error && ms && ms.activa && !ms.folio && FAC.estado.cotizacion.aceptada_en) await fac_enviarMicrosip({});\n}\n\n// ---------- Cliente aceptó → Microsip (alta/corrección del cliente + su cotización) ----------\n\nfunction fac_htmlMicrosip(aceptada) {\n  const ms = FAC.estado.microsip;\n  if (!ms || !ms.activa) return '';\n  const st = FAC.ms;\n  let cuerpo;\n  if (ms.folio) {\n    cuerpo = `<div class=\"cv-caja\" style=\"font-size:13px;\">✔ Ya está en Microsip como cotización <b>${escapeHtml(ms.folio)}</b>${ms.enviada_en ? ` <span style=\"color:var(--muted); font-size:11px;\">(${escapeHtml(ms.enviada_en.slice(0, 16).replace('T', ' '))})</span>` : ''}</div>`;\n  } else if (ms.faltantes && ms.faltantes.length) {\n    cuerpo = `<div class=\"cv-aviso\">⚠️ Todos los productos deben estar ligados a un artículo de Microsip. Falta:<ul style=\"margin:4px 0 0 18px; padding:0;\">${ms.faltantes.map(f => `<li>${escapeHtml(f)}</li>`).join('')}</ul>Edita la cotización y búscalos en Microsip.</div>`;\n  } else if (st.enviando) {\n    cuerpo = '<p style=\"font-size:13px; color:var(--muted);\">⏳ Enviando a Microsip…</p>';\n  } else if (st.similares) {\n    cuerpo = `<p style=\"font-size:13px; margin:4px 0 8px;\">Encontré clientes parecidos en Microsip. ¿Es alguno de estos?</p>\n      ${st.similares.map(c => `\n        <div class=\"cv-caja\" style=\"margin-bottom:8px; font-size:13px;\">\n          <div style=\"display:flex; gap:8px; align-items:flex-start; justify-content:space-between; flex-wrap:wrap;\">\n            <div style=\"flex:1; min-width:200px;\">\n              <b>${escapeHtml(c.nombre)}</b>${c.clave ? ` <span style=\"color:var(--muted);\">· clave ${escapeHtml(c.clave)}</span>` : ''}<br>\n              <span style=\"font-size:12px; color:var(--muted);\">${[c.rfc ? `RFC ${escapeHtml(c.rfc)}` : '', c.telefono ? `Tel. ${escapeHtml(c.telefono)}` : '', c.codigo_postal ? `CP ${escapeHtml(c.codigo_postal)}` : ''].filter(Boolean).join(' · ') || 'Sin RFC ni teléfono'}</span>\n              ${c.direccion ? `<br><span style=\"font-size:12px; color:var(--muted);\">${escapeHtml(c.direccion)}</span>` : ''}\n              <br><span style=\"font-size:11px; color:#e8a33d;\">${(c.motivos || []).map(escapeHtml).join(' · ')}</span>\n            </div>\n            <button class=\"primary\" onclick=\"fac_enviarMicrosip({ microsip_cliente_id: ${Number(c.cliente_id)} })\">Es este</button>\n          </div>\n        </div>`).join('')}\n      <button class=\"secondary\" style=\"width:100%;\" onclick=\"fac_enviarMicrosip({ nuevo: true })\">➕ Ninguno — darlo de alta como cliente nuevo</button>\n      <p style=\"font-size:11px; color:var(--muted); margin:6px 0 0;\">Si eliges uno, en Microsip solo se llenan los datos que estén vacíos (no se cambia nada de lo que ya tiene).</p>`;\n  } else if (aceptada) {\n    cuerpo = `<button class=\"primary\" style=\"width:100%;\" onclick=\"fac_enviarMicrosip({})\">📤 Enviar a Microsip (cliente + cotización)</button>`;\n  } else {\n    cuerpo = '<p style=\"font-size:12px; color:var(--muted); margin:4px 0;\">Al guardar se busca al cliente en Microsip (o se da de alta) y se crea ahí la cotización con los mismos artículos a precio de lista.</p>';\n  }\n  return `\n    <span class=\"cv-etq\" id=\"fac_ms\" style=\"margin-top:18px;\">🔗 Microsip</span>\n    ${st.error ? `<div class=\"cv-aviso\">⚠️ ${escapeHtml(st.error)}</div>` : (!ms.folio && ms.error && !st.aviso ? `<div class=\"cv-aviso\">⚠️ El último intento falló: ${escapeHtml(ms.error)}</div>` : '')}\n    ${st.aviso ? `<div style=\"font-size:13px; color:#4caf50; margin:6px 0;\">${st.aviso}</div>` : ''}\n    ${cuerpo}`;\n}\n\nasync function fac_enviarMicrosip(cuerpo) {\n  FAC.ms.enviando = true; FAC.ms.error = ''; FAC.ms.aviso = '';\n  fac_render();\n  try {\n    const r = await api(`/api/cotizaciones/${FAC.id}/microsip`, { method: 'POST', body: JSON.stringify(cuerpo || {}) });\n    if (r.estado === 'elegir_cliente') {\n      FAC.ms.similares = r.similares;\n    } else {\n      FAC.ms.similares = null;\n      FAC.estado.microsip.folio = r.folio;\n      FAC.estado.microsip.enviada_en = null;\n      FAC.estado.microsip.error = null;\n      const cli = r.cliente_creado ? `cliente nuevo <b>${escapeHtml(r.cliente_nombre)}</b>${r.cliente_clave ? ` (clave ${escapeHtml(r.cliente_clave)})` : ''}`\n                                   : `<b>${escapeHtml(r.cliente_nombre)}</b>${r.campos_completados.length ? ` — se completó: ${escapeHtml(r.campos_completados.join(', '))}` : ''}`;\n      FAC.ms.aviso = `✔ Cotización <b>${escapeHtml(r.folio)}</b> creada en Microsip para ${cli}. Total en Microsip: $${cot_fmt(r.total)}.`\n        + (r.avisos || []).map(a => `<br><span style=\"color:#e8a33d;\">⚠️ ${escapeHtml(a)}</span>`).join('');\n      if (FAC.alTerminar) FAC.alTerminar();\n    }\n  } catch (e) {\n    FAC.ms.error = e.message;\n  }\n  FAC.ms.enviando = false;\n  fac_render();\n  const ancla = document.getElementById('fac_ms');\n  if (ancla) ancla.scrollIntoView({ behavior: 'smooth', block: 'start' });\n}\n\nfunction fac_ubicacion() {\n"
