   "    </div>\n    <div id=\"microsipError\" class=\"error-msg\"></div>\n    <div id=\"microsipResultado\"></div>\n    <div id=\"ms_escritura\" style=\"margin-top:22px;\"></div>\n  `;\n  abrirModal(true);\n  if (config.microsip_host) ms_cargarEscritura();\n}\n\nlet MS_ESC = null;\n\nasync function ms_cargarEscritura() {\n  const caja = document.getElementById('ms_escritura');\n  if (!caja) return;\n  try {\n    MS_ESC = await api('/api/microsip/escritura');\n  } catch (e) {\n    caja.innerHTML = `<div class=\"error-msg\">${escapeHtml(e.message)}</div>`;\n    return;\n  }\n  ms_renderEscritura();\n}\n\nfunction ms_renderEscritura(resultadoHtml = '') {\n  const c = MS_ESC;\n  const caja = document.getElementById('ms_escritura');\n  if (!caja || !c) return;\n  cv_asegurarEstilos();\n  caja.innerHTML = `\n    <h3 style=\"margin:0 0 6px;\">📤 Enviar cotizaciones aceptadas a Microsip</h3>\n    <p style=\"font-size:12px; color:var(--muted); margin:0 0 10px;\">\n      Cuando el cliente acepta una cotización: se busca en Microsip (RFC, teléfono o nombre parecido), el vendedor elige si es uno de ellos\n      (solo se llenan sus datos vacíos) o se da de alta, y se crea la cotización en Microsip con los mismos artículos a precio de lista.\n      Todos los productos deben estar ligados a Microsip. Esto <b>escribe</b> en Microsip: usa un usuario de Firebird con permiso de escritura\n      (el de solo lectura de arriba no sirve) y corre el diagnóstico antes de activarlo.\n    </p>\n    <label style=\"display:flex; gap:8px; align-items:center; font-size:14px; margin-bottom:10px; cursor:pointer;\">\n      <input type=\"checkbox\" id=\"ms_esc_activa\" ${c.activa ? 'checked' : ''} style=\"width:auto;\" /> Activado\n    </label>\n    <div class=\"row-2\">\n      <div class=\"field\"><label>Usuario de Firebird con escritura</label><input id=\"ms_esc_usuario\" value=\"${escapeHtml(c.usuario || '')}\" placeholder=\"vacío = el de arriba\" autocomplete=\"off\" /></div>\n      <div class=\"field\"><label>Contraseña ${c.tiene_password ? '<span style=\"color:var(--muted); font-weight:400; text-transform:none;\">(ya hay una — vacío para no cambiarla)</span>' : ''}</label><input type=\"password\" id=\"ms_esc_password\" placeholder=\"${c.tiene_password ? '••••••••' : ''}\" autocomplete=\"new-password\" /></div>\n    </div>\n    <div class=\"field\">\n      <label>Artículo de Microsip para el “Flete en instalación” (se manda 1 unidad por hora)</label>\n      <div style=\"font-size:13px; margin-bottom:6px;\">${c.articulo_flete_id ? `✔ ${escapeHtml(c.articulo_flete_nombre || ('Artículo #' + c.articulo_flete_id))} <a href=\"#\" onclick=\"MS_ESC.articulo_flete_id=null; MS_ESC.articulo_flete_nombre=null; ms_renderEscritura(); return false;\">quitar</a>` : '<span style=\"color:#e8a33d;\">Sin elegir — las cotizaciones con flete no se podrán enviar.</span>'}</div>\n      <div style=\"display:flex; gap:6px;\"><input id=\"ms_esc_buscar\" placeholder=\"Busca por nombre, ej. flete\" onkeydown=\"if(event.key==='Enter'){ms_buscarArticuloFlete(this.nextElementSibling)}\" />\n        <button class=\"secondary\" onclick=\"ms_buscarArticuloFlete(this)\">Buscar</button></div>\n      <div id=\"ms_esc_resultados\"></div>\n      <p style=\"font-size:11px; color:var(--muted); margin:4px 0 0;\">Tip: que su precio de lista en Microsip sea el precio por hora (sin IVA).</p>\n    </div>\n    <div style=\"display:flex; gap:8px; margin-top:6px;\">\n      <button class=\"primary\" style=\"flex:1;\" onclick=\"ms_guardarEscritura(this)\">Guardar</button>\n      <button class=\"secondary\" style=\"flex:1;\" onclick=\"ms_diagnosticoEscritura(this)\">🩺 Diagnóstico (prueba sin guardar)</button>\n    </div>\n    <div id=\"ms_esc_resultado\">${resultadoHtml}</div>`;\n}\n\nasync function ms_buscarArticuloFlete(btn) {\n  const q = document.getElementById('ms_esc_buscar').value.trim();\n  const caja = document.getElementById('ms_esc_resultados');\n  if (!q) return;\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      const lista = await api(`/api/checador-precio/buscar?q=${encodeURIComponent(q)}`);\n      caja.innerHTML = (lista || []).slice(0, 12).map(a => `\n        <div style=\"display:flex; justify-content:space-between; gap:8px; align-items:center; font-size:13px; padding:4px 0; border-bottom:1px solid var(--line, #333);\">\n          <span>${escapeHtml(a.nombre)} <span style=\"color:var(--muted);\">${escapeHtml(a.clave || '')}</span></span>\n          <button class=\"secondary\" style=\"padding:3px 10px;\" onclick='ms_elegirFlete(${Number(a.articulo_id)}, ${JSON.stringify(a.nombre).replace(/'/g, \"&#39;\")})'>Elegir</button>\n        </div>`).join('') || '<p style=\"font-size:12px; color:var(--muted);\">Sin resultados.</p>';\n    } catch (e) { caja.innerHTML = `<div class=\"error-msg\">${escapeHtml(e.message)}</div>`; }\n  });\n}\n\nfunction ms_elegirFlete(id, nombre) {\n  ms_leerFormEscritura();\n  MS_ESC.articulo_flete_id = id; MS_ESC.articulo_flete_nombre = nombre;\n  ms_renderEscritura('<p style=\"font-size:12px; color:#e8a33d;\">Recuerda darle Guardar.</p>');\n}\n\nfunction ms_leerFormEscritura() {\n  MS_ESC.activa = document.getElementById('ms_esc_activa').checked;\n  MS_ESC.usuario = document.getElementById('ms_esc_usuario').value.trim();\n  MS_ESC._password = document.getElementById('ms_esc_password').value;\n}\n\nasync function ms_guardarEscritura(btn) {\n  ms_leerFormEscritura();\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      MS_ESC = await api('/api/microsip/escritura', { method: 'PUT', body: JSON.stringify({\n        activa: MS_ESC.activa, usuario: MS_ESC.usuario || null, password: MS_ESC._password ? MS_ESC._password : null,\n        articulo_flete_id: MS_ESC.articulo_flete_id || null, articulo_flete_nombre: MS_ESC.articulo_flete_nombre || null }) });\n      ms_renderEscritura(`<p style=\"font-size:13px; color:#4caf50;\">✔ Guardado${MS_ESC.activa ? ' — envío a Microsip ACTIVADO' : ' (apagado)'}.</p>`);\n    } catch (e) {\n      ms_renderEscritura(`<div class=\"error-msg\">${escapeHtml(e.message)}</div>`);\n    }\n  });\n}\n\nasync function ms_diagnosticoEscritura(btn) {\n  const caja = document.getElementById('ms_esc_resultado');\n  caja.innerHTML = '<p style=\"font-size:12px; color:var(--muted);\">⏳ Probando… (guarda antes si cambiaste el usuario)</p>';\n  await conBloqueoDeBoton(btn, async () => {\n    try {\n      const d = await api('/api/microsip/escritura/diagnostico', { method: 'POST' });\n      caja.innerHTML = `<div class=\"cv-caja\" style=\"font-size:13px; margin-top:10px;\">\n        ${d.pasos.map(p => `<div style=\"margin:3px 0;\">${p.ok ? '✅' : '❌'} <b>${escapeHtml(p.paso)}</b>${p.detalle ? ` — ${escapeHtml(p.detalle)}` : ''}</div>`).join('')}\n        <div style=\"margin-top:8px; font-weight:600; color:${d.ok ? '#4caf50' : '#e8a33d'};\">${d.ok ? 'Todo listo: Microsip aceptó la prueba. Ya puedes activarlo.' : 'Hay algo que corregir antes de activarlo (mándame esta pantalla).'}</div></div>`;\n    } catch (e) { caja.innerHTML = `<div class=\"error-msg\">${escapeHtml(e.message)}</div>`; }\n  });\n}\n\nasync function guardarConfigMicrosipUI(boton) {\n"
